-- 1. Villa en Caacupé, zona urbana
insert into brimmo.propiedades (type, operation, city, price, currency, land, built, beds, baths, video_id, lat, lng, title_es, title_fr, title_en, zone_es, zone_fr, zone_en, desc_es, desc_fr, desc_en, features_es, features_fr, features_en, published, featured, pendiente, orden)
select 'Villa', 'VENTA', 'Caacupé', 515000000, 'GS', 830, NULL, 2, NULL, 'jb6os04D16A', -25.3861, -57.1408, 'Villa en Caacupé, zona urbana', 'Villa à Caacupé, zone urbaine', 'Villa in Caacupé, urban area', 'Zona urbana', 'Zone urbaine', 'Urban area', 'Villa en un barrio residencial de Caacupé, con entorno tranquilo y todos los servicios a pocos minutos. El terreno de 830 m² está completamente cerrado y la casa cuenta con dos dormitorios, living luminoso y una amplia terraza para aprovechar el clima durante todo el año. Tiene reserva de agua instalada, vista despejada al verde y acceso cómodo en cualquier época.', 'Villa dans un quartier résidentiel de Caacupé, dans un environnement paisible avec tous les services à quelques minutes. Le terrain de 830 m² est entièrement clôturé et la maison compte deux chambres, un salon lumineux et une grande terrasse pour profiter du climat toute l''année. Réserve d''eau installée, vue dégagée sur la verdure et accès facile en toute saison.', 'Villa in a residential neighbourhood of Caacupé, in a quiet setting with every service a few minutes away. The 830 m² plot is fully fenced and the house has two bedrooms, a bright living room and a wide terrace to enjoy the climate year round. It has an installed water reserve, open views over greenery and easy access in any season.', '["Terreno cerrado","Living luminoso","Amplia terraza","Reserva de agua","Barrio tranquilo y seguro","Comercios y escuelas cerca"]'::jsonb, '["Terrain clôturé","Salon lumineux","Grande terrasse","Réserve d''eau","Quartier calme et sécurisé","Commerces et écoles à proximité"]'::jsonb, '["Fenced plot","Bright living room","Wide terrace","Water reserve","Quiet, secure neighbourhood","Shops and schools nearby"]'::jsonb, true, true, NULL, 10
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Villa en Caacupé, zona urbana' and city = 'Caacupé');

-- 2. Villa a 5 minutos de Caacupé
insert into brimmo.propiedades (type, operation, city, price, currency, land, built, beds, baths, video_id, lat, lng, title_es, title_fr, title_en, zone_es, zone_fr, zone_en, desc_es, desc_fr, desc_en, features_es, features_fr, features_en, published, featured, pendiente, orden)
select 'Villa', 'VENTA', 'Caacupé', 890000000, 'GS', NULL, 220, NULL, NULL, 'wgp7iHkPP9g', -25.3861, -57.1408, 'Villa a 5 minutos de Caacupé', 'Villa à 5 minutes de Caacupé', 'Villa 5 minutes from Caacupé', 'A 5 minutos del centro', 'À 5 minutes du centre', '5 minutes from the centre', 'Villa de una sola planta de 220 m², a cinco minutos de Caacupé y a una hora y media de Asunción. Está a 50 metros de la ruta asfaltada, en una zona tranquila y segura.', 'Villa de plain-pied de 220 m², à cinq minutes de Caacupé et à une heure et demie d''Asunción. Elle se trouve à 50 mètres de la route asphaltée, dans une zone calme et sécurisée.', 'Single-storey villa of 220 m², five minutes from Caacupé and an hour and a half from Asunción. It sits 50 metres from the paved road, in a quiet and secure area.', '["Una sola planta","A 50 m de ruta asfaltada","Zona segura"]'::jsonb, '["De plain-pied","À 50 m de la route asphaltée","Zone sécurisée"]'::jsonb, '["Single storey","50 m from the paved road","Secure area"]'::jsonb, false, false, 'La portada de la web anterior la describe como «villa de lujo con piscina», pero el catálogo no menciona piscina. Confirmar antes de publicar.', 20
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Villa a 5 minutos de Caacupé' and city = 'Caacupé');

-- 3. Quinta de 1,6 hectáreas en Atyrá
insert into brimmo.propiedades (type, operation, city, price, currency, land, built, beds, baths, video_id, lat, lng, title_es, title_fr, title_en, zone_es, zone_fr, zone_en, desc_es, desc_fr, desc_en, features_es, features_fr, features_en, published, featured, pendiente, orden)
select 'Quinta', 'VENTA', 'Atyrá', 292000000, 'GS', 16000, 80, 3, 1, '2pG6a87NuPk', -25.2686, -57.1736, 'Quinta de 1,6 hectáreas en Atyrá', 'Quinta de 1,6 hectare à Atyrá', '1.6-hectare country home in Atyrá', NULL, NULL, NULL, 'Quinta de 1,6 hectáreas en Atyrá, a 30 minutos de Caacupé y 60 km de Asunción. El terreno es plano, está completamente cerrado y cuenta con pozo de agua potable. Tiene una gran variedad de árboles frutales —cítricos, mango, banana, guayaba, cacao— y dos colmenas para producción artesanal de miel. La construcción principal, de 80 m², es a refaccionar: tres dormitorios de 8, 9 y 14 m², entrada y living de 15 m², baño de 3,20 m² y cocina exterior de 20 m².', 'Quinta de 1,6 hectare à Atyrá, à 30 minutes de Caacupé et 60 km d''Asunción. Le terrain est plat, entièrement clôturé et dispose d''un puits d''eau potable. Il compte de nombreux arbres fruitiers — citronniers, orangers, pamplemoussiers, manguiers, bananiers, goyaviers, cacaoyers — et deux ruches pour une production artisanale de miel. Le bâti principal, de 80 m², est à rénover : trois chambres de 8, 9 et 14 m², entrée et salon de 15 m², salle de bain de 3,20 m² et cuisine extérieure de 20 m².', 'A 1.6-hectare country property in Atyrá, 30 minutes from Caacupé and 60 km from Asunción. The land is flat, fully fenced and has a drinking-water well. It holds a wide range of fruit trees — lemon, orange, grapefruit, mango, banana, guava, cacao — and two beehives for small-scale honey production. The main 80 m² building needs renovation: three bedrooms of 8, 9 and 14 m², a 15 m² entrance and living room, a 3.20 m² bathroom and a 20 m² outdoor kitchen.', '["Terreno plano y cerrado","Pozo de agua potable","Árboles frutales variados","Dos colmenas","Cocina exterior de 20 m²","Construcción a refaccionar"]'::jsonb, '["Terrain plat et clôturé","Puits d''eau potable","Nombreux arbres fruitiers","Deux ruches","Cuisine extérieure de 20 m²","Bâti à rénover"]'::jsonb, '["Flat, fenced land","Drinking-water well","Many fruit trees","Two beehives","20 m² outdoor kitchen","Building needs renovation"]'::jsonb, false, false, 'Conflicto de precio: la portada publica 37.600 USD y el catálogo 292.000.000 Gs (≈39.000 USD). Confirmar precio y moneda de referencia.', 30
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Quinta de 1,6 hectáreas en Atyrá' and city = 'Atyrá');

