select 'Terreno', 'VENTA', 'Tobatí', 150000, 'USD', 78000, NULL, NULL, NULL, NULL, -25.2536, -57.0783, 'Terreno de 7,8 hectáreas sobre ruta Tobatí–Aguaity', 'Terrain de 7,8 hectares sur la route Tobatí–Aguaity', '7.8-hectare plot on the Tobatí–Aguaity road', 'Aguaity', 'Aguaity', 'Aguaity', 'Propiedad rural de 7,8 hectáreas en una ubicación privilegiada de La Cordillera, a pocos minutos de Tobatí. Tiene 217 metros lineales de frente sobre la ruta asfaltada Tobatí–Aguaity y acceso directo al arroyo Ytú. El título y los impuestos están en regla, listos para transferencia, e incluye plano de mensura georreferenciado inscripto en el Servicio Nacional de Catastro. Apta para estancia, explotación agrícola, proyecto turístico, loteamiento o inversión.', 'Propriété rurale de 7,8 hectares dans un emplacement privilégié de La Cordillera, à quelques minutes de Tobatí. Elle bénéficie de 217 mètres linéaires de façade sur la route asphaltée Tobatí–Aguaity et d''un accès direct au ruisseau Ytú. Titre de propriété et taxes en règle, prêt pour le transfert, avec un plan de bornage géoréférencé enregistré auprès du Service national du cadastre. Idéale pour un domaine, une exploitation agricole, un projet touristique, un lotissement ou un investissement.', 'A 7.8-hectare rural property in a prime spot in La Cordillera, minutes from Tobatí. It has 217 linear metres of frontage on the paved Tobatí–Aguaity road and direct access to the Ytú stream. Title and taxes are in order and ready for transfer, and it includes a georeferenced survey plan registered with the National Cadastre Service. Suited to an estate, farming, a tourism project, a subdivision or an investment.', '["217 m de frente sobre ruta asfaltada","Acceso directo al arroyo Ytú","Título e impuestos en regla","Plano de mensura georreferenciado"]'::jsonb, '["217 m de façade sur route asphaltée","Accès direct au ruisseau Ytú","Titre et taxes en règle","Plan de bornage géoréférencé"]'::jsonb, '["217 m of paved-road frontage","Direct access to the Ytú stream","Title and taxes in order","Georeferenced survey plan"]'::jsonb, true, false, NULL, 60
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Terreno de 7,8 hectáreas sobre ruta Tobatí–Aguaity' and city = 'Tobatí');

-- 7. Quinta de 2 hectáreas sobre la ruta de Atyrá
insert into brimmo.propiedades (type, operation, city, price, currency, land, built, beds, baths, video_id, lat, lng, title_es, title_fr, title_en, zone_es, zone_fr, zone_en, desc_es, desc_fr, desc_en, features_es, features_fr, features_en, published, featured, pendiente, orden)
select 'Quinta', 'VENTA', 'Caacupé', 180000, 'USD', 20000, NULL, NULL, NULL, NULL, -25.3861, -57.1408, 'Quinta de 2 hectáreas sobre la ruta de Atyrá', 'Quinta de 2 hectares sur la route d''Atyrá', '2-hectare country home on the Atyrá road', 'Ruta de Atyrá', 'Route d''Atyrá', 'Atyrá road', 'Quinta a cinco minutos de Caacupé, sobre la ruta de Atyrá, en una zona tranquila y arbolada. La construcción principal es sólida y funcional, y el terreno es plano y de acceso fácil desde la ruta. Cuenta con quincho amplio con parrilla y piscina, con espacio suficiente para ampliar o desarrollar nuevas construcciones. Ideal para un proyecto ecoturístico, una residencia familiar o una casa de fin de semana.', 'Quinta à cinq minutes de Caacupé, sur la route d''Atyrá, dans une zone calme et verdoyante. La construction principale est solide et fonctionnelle, et le terrain est plat, d''accès facile depuis la route. Elle dispose d''un grand quincho avec barbecue et d''une piscine, avec assez d''espace pour agrandir ou développer d''autres constructions. Idéale pour un projet éco-touristique, une résidence familiale ou une maison de vacances.', 'A country property five minutes from Caacupé, on the Atyrá road, in a quiet, wooded area. The main building is solid and functional, and the land is flat with easy access from the road. It has a large covered barbecue area and a pool, with room to extend or add further buildings. Ideal for an eco-tourism project, a family home or a weekend house.', '["Quincho amplio con parrilla","Piscina","Terreno plano","Acceso directo desde la ruta","Espacio para ampliar"]'::jsonb, '["Grand quincho avec barbecue","Piscine","Terrain plat","Accès direct depuis la route","Espace pour agrandir"]'::jsonb, '["Large covered barbecue area","Swimming pool","Flat land","Direct road access","Room to extend"]'::jsonb, true, false, NULL, 70
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Quinta de 2 hectáreas sobre la ruta de Atyrá' and city = 'Caacupé');

