select 'Rancho', 'VENTA', 'Eusebio Ayala', 840000000, 'GS', NULL, NULL, NULL, NULL, NULL, -25.3833, -56.9333, 'Rancho en Eusebio Ayala', 'Ranch à Eusebio Ayala', 'Ranch in Eusebio Ayala', 'A 20 km de Caacupé', 'À 20 km de Caacupé', '20 km from Caacupé', 'Propiedad a 20 km de Caacupé, junto a Eusebio Ayala, donde se encuentran todos los servicios esenciales: comercios, escuelas, centros de salud, restaurantes y estaciones de servicio. Tiene frente sobre ruta asfaltada, con acceso cómodo durante todo el año. Apta para un proyecto agrícola, un loteamiento, una residencia de campo, una inversión o un desarrollo turístico.', 'Propriété à 20 km de Caacupé, près d''Eusebio Ayala, où se trouvent tous les services essentiels : commerces, écoles, centres de santé, restaurants et stations-service. Elle dispose d''une façade sur route asphaltée, avec un accès facile toute l''année. Idéale pour un projet agricole, un lotissement, une résidence de campagne, un investissement ou un projet touristique.', 'A property 20 km from Caacupé, next to Eusebio Ayala, where all essential services are available: shops, schools, health centres, restaurants and petrol stations. It has frontage on a paved road with easy access year round. Suited to a farming project, a subdivision, a country residence, an investment or a tourism development.', '["Frente sobre ruta asfaltada","Acceso cómodo todo el año","Servicios esenciales cerca","Apto para proyecto agrícola o turístico"]'::jsonb, '["Façade sur route asphaltée","Accès facile toute l''année","Services essentiels à proximité","Adaptée à un projet agricole ou touristique"]'::jsonb, '["Paved-road frontage","Easy access year round","Essential services nearby","Suited to farming or tourism"]'::jsonb, false, false, 'El título indica 10 hectáreas y la descripción 9 hectáreas. Confirmar superficie según título de propiedad.', 120
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Rancho en Eusebio Ayala' and city = 'Eusebio Ayala');

-- 13. Terreno de 14 hectáreas en Ita Yvu Guasu
insert into brimmo.propiedades (type, operation, city, price, currency, land, built, beds, baths, video_id, lat, lng, title_es, title_fr, title_en, zone_es, zone_fr, zone_en, desc_es, desc_fr, desc_en, features_es, features_fr, features_en, published, featured, pendiente, orden)
select 'Terreno', 'VENTA', 'Caacupé', 1470000000, 'GS', 140000, NULL, NULL, NULL, NULL, -25.3861, -57.1408, 'Terreno de 14 hectáreas en Ita Yvu Guasu', 'Terrain de 14 hectares à Ita Yvu Guasu', '14-hectare plot in Ita Yvu Guasu', 'Ita Yvu Guasu', 'Ita Yvu Guasu', 'Ita Yvu Guasu', 'Propiedad de 14 hectáreas a pocos minutos de Caacupé, con un arroyo natural que la atraviesa y cerca del 70% de vegetación natural entre arbustos y árboles. El acceso es cómodo todo el año, con 3 km de camino de tierra, y la ruta de acceso está en proceso de asfaltado. Es una zona valorada por las comunidades suiza y alemana. Apta para estancia privada, proyecto turístico o ecológico, granja autónoma, ganadería, agroforestería o loteamiento rural.', 'Propriété de 14 hectares à quelques minutes de Caacupé, traversée par un ruisseau naturel et couverte à près de 70 % de végétation naturelle, arbustes et arbres. L''accès est aisé toute l''année, avec 3 km de piste, et la route d''accès est en cours de bitumage. C''est un secteur apprécié des communautés suisse et allemande. Idéale pour un domaine privé, un projet touristique ou écologique, une ferme autonome, de l''élevage, de l''agroforesterie ou un lotissement rural.', 'A 14-hectare property minutes from Caacupé, crossed by a natural stream and around 70% covered in natural vegetation, shrubs and trees. Access is comfortable year round over 3 km of track, and the access road is being paved. The area is favoured by the Swiss and German communities. Suited to a private estate, a tourism or ecological project, a self-sufficient farm, livestock, agroforestry or a rural subdivision.', '["Arroyo natural que atraviesa la propiedad","70% de vegetación natural","A 3 km de camino de tierra","Ruta de acceso en proceso de asfaltado"]'::jsonb, '["Ruisseau naturel traversant la propriété","70 % de végétation naturelle","3 km de piste","Route d''accès en cours de bitumage"]'::jsonb, '["Natural stream crossing the land","70% natural vegetation","3 km of track","Access road being paved"]'::jsonb, false, false, 'Doble precio: 1.470.000.000 Gs y «~212.000» con la moneda ilegible en el original. Los dos valores no coinciden entre sí. Confirmar.', 130
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Terreno de 14 hectáreas en Ita Yvu Guasu' and city = 'Caacupé');

-- 14. Terreno de 4.400 m² en Cabañas
insert into brimmo.propiedades (type, operation, city, price, currency, land, built, beds, baths, video_id, lat, lng, title_es, title_fr, title_en, zone_es, zone_fr, zone_en, desc_es, desc_fr, desc_en, features_es, features_fr, features_en, published, featured, pendiente, orden)
select 'Terreno', 'VENTA', 'Caacupé', 357000000, 'GS', 4400, NULL, NULL, NULL, NULL, -25.3861, -57.1408, 'Terreno de 4.400 m² en Cabañas', 'Terrain de 4 400 m² à Cabañas', '4,400 m² plot in Cabañas', 'Cabañas', 'Cabañas', 'Cabañas', 'Terreno de 4.400 m² en Cabañas, a pocos minutos del centro de Caacupé. Está completamente cerrado con portón de acceso, cuenta con agua y electricidad, y queda a 700 metros de la ruta asfaltada, con comercio de cercanía y acceso cómodo todo el año. Ya tiene un pequeño galpón/establo en el terreno.', 'Terrain de 4 400 m² à Cabañas, à quelques minutes du centre de Caacupé. Entièrement clôturé avec portail d''accès, il dispose de l''eau et de l''électricité et se trouve à 700 mètres de la route asphaltée, avec commerce de proximité et un accès facile toute l''année. Un petit bâtiment/étable est déjà présent sur le terrain.', 'A 4,400 m² plot in Cabañas, minutes from the centre of Caacupé. Fully fenced with an access gate, it has water and electricity and sits 700 metres from the paved road, with a local shop nearby and easy access year round. A small shed/stable is already built on the land.', '["Completamente cerrado con portón","Agua y electricidad","A 700 m de ruta asfaltada","Galpón/establo ya construido"]'::jsonb, '["Entièrement clôturé avec portail","Eau et électricité","À 700 m de la route asphaltée","Petit bâtiment/étable déjà construit"]'::jsonb, '["Fully fenced with gate","Water and electricity","700 m from the paved road","Small shed/stable already built"]'::jsonb, true, false, NULL, 140
where not exists (select 1 from brimmo.propiedades
                  where title_es = 'Terreno de 4.400 m² en Cabañas' and city = 'Caacupé');

